def transform(grid):
    m, n = len(grid), len(grid[0])
    result = [row[:] for row in grid]
    for r in range(m):
        # Find all boundary positions in this row
        boundary_color = None
        border_positions = []
        for c in range(n):
            if grid[r][c] != 0:  # non-background
                if boundary_color is None:
                    boundary_color = grid[r][c]
                border_positions.append(c)

        if len(border_positions) >= 2:
            # Fill between first and last boundary position
            fill_color = boundary_color - 1 if boundary_color > 0 else 0
            start, end = border_positions[0], border_positions[-1]
            for c in range(start + 1, end):
                if result[r][c] == 0:
                    result[r][c] = fill_color
    return result

